document.getElementById('uploadModeSelect').addEventListener('change',function(){var e=document.getElementById('imageKitKeyContainer');'imagekit'===this.value?(e.classList.remove('d-none'),e.classList.add('d-block')):(e.classList.remove('d-block'),e.classList.add('d-none'))});document.getElementById('geminiSwitch').addEventListener('change',function(){var e=document.getElementById('geminiAiContainer'),t=document.getElementById('enable_gemini');this.checked?(e.classList.remove('d-none'),e.classList.add('d-flex'),t.value='yes'):(e.classList.remove('d-flex'),e.classList.add('d-none'),t.value='no')});document.getElementById('cloudflareSwitch').addEventListener('change',function(){var e=document.getElementById('cloudflareContainer'),t=document.getElementById('enable_cloudflare');this.checked?(e.classList.remove('d-none'),e.classList.add('d-flex'),t.value='yes'):(e.classList.remove('d-flex'),e.classList.add('d-none'),t.value='no')});document.getElementById('indexnowSwitch').addEventListener('change',function(){var e=document.getElementById('indexnowContainer'),t=document.getElementById('indexnow');this.checked?(e.classList.remove('d-none'),e.classList.add('d-flex'),t.value='yes'):(e.classList.remove('d-flex'),e.classList.add('d-none'),t.value='no')});document.querySelectorAll('.theme-swatch').forEach(function(e){e.addEventListener('click',function(){var t=this.getAttribute('data-theme'),n=document.getElementById('public_theme');if(n){n.value=t;document.querySelectorAll('.theme-swatch').forEach(function(e){e.style.outline=''});this.style.outline='2px solid #0d6efd';this.style.outlineOffset='1px'}})});